(* ==============================================
   PID Controller + Process Simulation
   Language: Structured Text (ST)

   This program demonstrates:
   1. A first-order process simulation (thermal model)
   2. A PID controller using the built-in PID() function
   3. Adjustable gains via OPC variables
   ============================================== *)

VAR
  (* Process simulation *)
  pv : REAL;
  sp : REAL;
  output : REAL;
  disturbance : REAL;
  gain : REAL;
  tau : REAL;
  noise : REAL;
  dt : REAL;
  dpv : REAL;
  (* PID parameters *)
  kp : REAL;
  ki : REAL;
  kd : REAL;
  outMin : REAL;
  outMax : REAL;
  enabled : REAL;
END_VAR

(* Read simulation parameters *)
gain := Read('Simulation.ProcessGain');
tau := Read('Simulation.TimeConstant');
noise := Read('Simulation.NoiseAmplitude');
disturbance := Read('Process.CoolingDisturbance');

(* Read current process state *)
pv := Read('Process.Temperature');
sp := Read('Process.Setpoint');

(* Read PID gains from operator-adjustable variables *)
kp := Read('PID.Kp');
ki := Read('PID.Ki');
kd := Read('PID.Kd');
outMin := Read('PID.OutMin');
outMax := Read('PID.OutMax');
enabled := Read('PID.Enabled');

(* --- PID Controller --- *)
IF enabled > 0.5 THEN
  output := PID('main_loop', pv, sp, kp, ki, kd, outMin, outMax);
ELSE
  output := 0.0;
END_IF;

Write('Process.HeaterOutput', output);

(* --- Process Simulation (first-order + disturbance + noise) --- *)
(* dPV/dt = (-PV + K * output - disturbance * tau) / tau *)
dt := 0.1;
dpv := (-pv + gain * output - disturbance * tau) / tau;
pv := pv + dpv * dt;

(* Add measurement noise *)
pv := pv + (Random() - 0.5) * 2.0 * noise;

(* Clamp to physical range *)
IF pv < 0.0 THEN pv := 0.0; END_IF;
IF pv > 200.0 THEN pv := 200.0; END_IF;

Write('Process.Temperature', pv);
